-- SQLite uses date(...), strftime(...), and julianday(...); replace with DATE_TRUNC/INTERVAL/DATE_PART equivalents in PostgreSQL, or DATE_FORMAT/DATEDIFF in MySQL.
-- Q01 [Basic] Customers by country
SELECT country, COUNT(*) AS customers FROM customers GROUP BY country ORDER BY customers DESC;
-- Q02 [Basic] Active vs cancelled subscriptions
SELECT status, COUNT(*) AS subscriptions FROM subscriptions GROUP BY status ORDER BY status;
-- Q03 [Basic] Revenue by plan (paid payments)
SELECT CASE p.amount WHEN 9 THEN 'Basic' WHEN 29 THEN 'Pro' ELSE 'Business' END AS plan_name,SUM(p.amount) AS paid_revenue FROM subscriptions s JOIN payments p ON p.subscription_id=s.subscription_id WHERE p.status='paid' GROUP BY CASE p.amount WHEN 9 THEN 'Basic' WHEN 29 THEN 'Pro' ELSE 'Business' END ORDER BY paid_revenue DESC;
-- Q04 [Basic] Monthly signups
SELECT substr(signup_date,1,7) AS signup_month, COUNT(*) AS signups FROM customers GROUP BY signup_month ORDER BY signup_month;
-- Q05 [Basic] Average tickets per customer
SELECT ROUND(1.0*COUNT(t.ticket_id)/(SELECT COUNT(*) FROM customers),3) AS avg_tickets_per_customer FROM support_tickets t;
-- Q06 [Basic] Top 5 countries by paid revenue
SELECT c.country, SUM(p.amount) AS paid_revenue FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id JOIN payments p ON p.subscription_id=s.subscription_id WHERE p.status='paid' GROUP BY c.country ORDER BY paid_revenue DESC LIMIT 5;
-- Q07 [Joins] Paid revenue by acquisition channel
SELECT c.acquisition_channel, SUM(p.amount) AS paid_revenue FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id JOIN payments p ON p.subscription_id=s.subscription_id WHERE p.status='paid' GROUP BY c.acquisition_channel ORDER BY paid_revenue DESC;
-- Q08 [Joins] Churn rate by channel (cancelled subscriptions / subscriptions)
SELECT c.acquisition_channel, COUNT(CASE WHEN s.status='cancelled' THEN 1 END) AS cancelled, COUNT(*) AS subscriptions, ROUND(1.0*COUNT(CASE WHEN s.status='cancelled' THEN 1 END)/COUNT(*),4) AS churn_rate FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id GROUP BY c.acquisition_channel ORDER BY churn_rate DESC;
-- Q09 [Joins] Average subscription length by plan (days)
SELECT pl.plan_name, ROUND(AVG(julianday(COALESCE(s.end_date,'2024-12-31'))-julianday(s.start_date)),1) AS avg_days FROM plans pl JOIN subscriptions s ON s.plan_id=pl.plan_id GROUP BY pl.plan_name ORDER BY avg_days DESC;
-- Q10 [Joins] Customers with failed payments
SELECT c.customer_id,c.country,c.acquisition_channel,COUNT(*) AS failed_payments FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id JOIN payments p ON p.subscription_id=s.subscription_id WHERE p.status='failed' GROUP BY c.customer_id,c.country,c.acquisition_channel ORDER BY failed_payments DESC,c.customer_id;
-- Q11 [Joins] Customers with no support tickets
SELECT c.customer_id,c.country,c.acquisition_channel FROM customers c LEFT JOIN support_tickets t ON t.customer_id=c.customer_id WHERE t.ticket_id IS NULL ORDER BY c.customer_id;
-- Q12 [Joins] Plan mix by country
SELECT c.country,pl.plan_name,COUNT(*) AS subscriptions FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id JOIN plans pl ON pl.plan_id=s.plan_id GROUP BY c.country,pl.plan_name ORDER BY c.country,subscriptions DESC;
-- Q13 [Joins] Refund rate by plan (refunds / all payment rows)
SELECT CASE p.amount WHEN 9 THEN 'Basic' WHEN 29 THEN 'Pro' ELSE 'Business' END AS plan_name,COUNT(CASE WHEN p.status='refunded' THEN 1 END) AS refunds,COUNT(*) AS payments,ROUND(1.0*COUNT(CASE WHEN p.status='refunded' THEN 1 END)/COUNT(*),4) AS refund_rate FROM subscriptions s JOIN payments p ON p.subscription_id=s.subscription_id GROUP BY CASE p.amount WHEN 9 THEN 'Basic' WHEN 29 THEN 'Pro' ELSE 'Business' END ORDER BY refund_rate DESC;
-- Q14 [CTE] MRR by month-end from active subscriptions and latest paid amount that month
WITH months AS (SELECT date('2023-01-01','+'||n||' months','start of month','+1 month','-1 day') AS month_end FROM (WITH RECURSIVE m(n) AS (SELECT 0 UNION ALL SELECT n+1 FROM m WHERE n<23) SELECT n FROM m)), ranked AS (SELECT strftime('%Y-%m',p.payment_date) AS month_key,p.subscription_id,p.amount,ROW_NUMBER() OVER(PARTITION BY strftime('%Y-%m',p.payment_date),p.subscription_id ORDER BY p.payment_date DESC,p.payment_id DESC) AS rn FROM payments p WHERE p.status='paid') SELECT strftime('%Y-%m',m.month_end) AS month,ROUND(SUM(CASE WHEN s.start_date<=m.month_end AND (s.end_date IS NULL OR s.end_date>m.month_end) THEN COALESCE(r.amount,pl.monthly_price) ELSE 0 END),2) AS mrr FROM months m JOIN subscriptions s ON s.start_date<=m.month_end LEFT JOIN plans pl ON pl.plan_id=s.plan_id LEFT JOIN ranked r ON r.subscription_id=s.subscription_id AND r.month_key=strftime('%Y-%m',m.month_end) AND r.rn=1 GROUP BY month ORDER BY month;
-- Q15 [CTE] Customers above average observed paid lifetime value
WITH ltv AS (SELECT c.customer_id,c.country,c.acquisition_channel,SUM(CASE WHEN p.status='paid' THEN p.amount ELSE 0 END) AS lifetime_value FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id LEFT JOIN payments p ON p.subscription_id=s.subscription_id GROUP BY c.customer_id) SELECT customer_id,country,acquisition_channel,lifetime_value FROM ltv WHERE lifetime_value>(SELECT AVG(lifetime_value) FROM ltv) ORDER BY lifetime_value DESC;
-- Q16 [CTE] Month-over-month MRR growth
WITH RECURSIVE m(n) AS (SELECT 0 UNION ALL SELECT n+1 FROM m WHERE n<23), months AS (SELECT date('2023-01-01','+'||n||' months','start of month','+1 month','-1 day') AS month_end FROM m), ranked AS (SELECT strftime('%Y-%m',p.payment_date) AS month_key,p.subscription_id,p.amount,ROW_NUMBER() OVER(PARTITION BY strftime('%Y-%m',p.payment_date),p.subscription_id ORDER BY p.payment_date DESC,p.payment_id DESC) AS rn FROM payments p WHERE p.status='paid'), monthly AS (SELECT strftime('%Y-%m',m.month_end) AS month,ROUND(SUM(CASE WHEN s.start_date<=m.month_end AND (s.end_date IS NULL OR s.end_date>m.month_end) THEN COALESCE(r.amount,pl.monthly_price) ELSE 0 END),2) AS mrr FROM months m JOIN subscriptions s ON s.start_date<=m.month_end LEFT JOIN plans pl ON pl.plan_id=s.plan_id LEFT JOIN ranked r ON r.subscription_id=s.subscription_id AND r.month_key=strftime('%Y-%m',m.month_end) AND r.rn=1 GROUP BY month), lagged AS (SELECT month,mrr,LAG(mrr) OVER(ORDER BY month) AS previous_month_mrr FROM monthly) SELECT month,mrr,previous_month_mrr,ROUND(100.0*(mrr-previous_month_mrr)/NULLIF(previous_month_mrr,0),2) AS growth_pct FROM lagged ORDER BY month;
-- Q17 [CTE] Customers with Basic-to-Pro upgrade evidence
SELECT c.customer_id,MIN(p.payment_date) AS first_pro_price_date FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id JOIN payments p ON p.subscription_id=s.subscription_id WHERE s.plan_id=1 AND p.status='paid' AND p.amount=29 GROUP BY c.customer_id ORDER BY first_pro_price_date;
-- Q18 [CTE] Days from first paid payment to cancellation
WITH first_pay AS (SELECT s.subscription_id,MIN(p.payment_date) AS first_paid_date FROM subscriptions s JOIN payments p ON p.subscription_id=s.subscription_id WHERE p.status='paid' GROUP BY s.subscription_id) SELECT s.subscription_id,s.customer_id,CAST(julianday(s.end_date)-julianday(f.first_paid_date) AS INTEGER) AS days_to_cancel FROM subscriptions s JOIN first_pay f ON f.subscription_id=s.subscription_id WHERE s.status='cancelled' ORDER BY days_to_cancel;
-- Q19 [CTE] High-ticket customers (3+) who churned
WITH ticket_counts AS (SELECT customer_id,COUNT(*) AS ticket_count FROM support_tickets GROUP BY customer_id) SELECT c.customer_id,tc.ticket_count,s.cancel_reason FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id JOIN ticket_counts tc ON tc.customer_id=c.customer_id WHERE s.status='cancelled' AND tc.ticket_count>=3 ORDER BY tc.ticket_count DESC;
-- Q20 [Window] Rank acquisition channels by average paid LTV
WITH x AS (SELECT c.acquisition_channel,c.customer_id,SUM(CASE WHEN p.status='paid' THEN p.amount ELSE 0 END) AS ltv FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id LEFT JOIN payments p ON p.subscription_id=s.subscription_id GROUP BY c.acquisition_channel,c.customer_id), y AS (SELECT acquisition_channel,AVG(ltv) AS avg_ltv FROM x GROUP BY acquisition_channel) SELECT acquisition_channel,ROUND(avg_ltv,2) AS avg_ltv,RANK() OVER(ORDER BY avg_ltv DESC) AS channel_rank FROM y ORDER BY channel_rank;
-- Q21 [Window] Running total of paid revenue by month
WITH m AS (SELECT substr(payment_date,1,7) AS month,SUM(amount) AS revenue FROM payments WHERE status='paid' GROUP BY month) SELECT month,revenue,SUM(revenue) OVER(ORDER BY month ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_revenue FROM m ORDER BY month;
-- Q22 [Window] Three-month moving average of signups
WITH m AS (SELECT substr(signup_date,1,7) AS month,COUNT(*) AS signups FROM customers GROUP BY month) SELECT month,signups,ROUND(AVG(signups) OVER(ORDER BY month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) AS moving_avg_3m FROM m ORDER BY month;
-- Q23 [Window] Rank customers within country by paid revenue
WITH x AS (SELECT c.country,c.customer_id,SUM(CASE WHEN p.status='paid' THEN p.amount ELSE 0 END) AS revenue FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id LEFT JOIN payments p ON p.subscription_id=s.subscription_id GROUP BY c.country,c.customer_id) SELECT country,customer_id,revenue,RANK() OVER(PARTITION BY country ORDER BY revenue DESC) AS country_rank FROM x ORDER BY country,country_rank,customer_id;
-- Q24 [Window] Previous-month paid payment comparison
WITH m AS (SELECT substr(payment_date,1,7) AS month,SUM(CASE WHEN status='paid' THEN amount ELSE 0 END) AS paid_revenue FROM payments GROUP BY month) SELECT month,paid_revenue,LAG(paid_revenue) OVER(ORDER BY month) AS previous_month_revenue,paid_revenue-LAG(paid_revenue) OVER(ORDER BY month) AS change_amount FROM m ORDER BY month;
-- Q25 [Window] Percentile rank of ticket resolution time
SELECT ticket_id,customer_id,resolution_hours,PERCENT_RANK() OVER(ORDER BY resolution_hours) AS resolution_percentile FROM support_tickets ORDER BY resolution_percentile;
-- Q26 [Advanced] Signup cohort retention months 0 through 12 (active subs at month end)
WITH RECURSIVE offsets(n) AS (SELECT 0 UNION ALL SELECT n+1 FROM offsets WHERE n<12), cohorts AS (SELECT substr(signup_date,1,7) AS cohort_month,customer_id FROM customers), cohort_sizes AS (SELECT cohort_month,COUNT(*) AS cohort_size FROM cohorts GROUP BY cohort_month), grid AS (SELECT cs.cohort_month,cs.cohort_size,o.n,date(cs.cohort_month||'-01','+'||o.n||' months','start of month','+1 month','-1 day') AS month_end FROM cohort_sizes cs CROSS JOIN offsets o WHERE date(cs.cohort_month||'-01','+'||o.n||' months')<='2024-12-31') SELECT g.cohort_month,g.n AS months_since_signup,g.cohort_size,COUNT(DISTINCT CASE WHEN s.start_date<=g.month_end AND (s.end_date IS NULL OR s.end_date>g.month_end) THEN co.customer_id END) AS retained_customers,ROUND(1.0*COUNT(DISTINCT CASE WHEN s.start_date<=g.month_end AND (s.end_date IS NULL OR s.end_date>g.month_end) THEN co.customer_id END)/g.cohort_size,4) AS retention_rate FROM grid g JOIN cohorts co ON co.cohort_month=g.cohort_month LEFT JOIN subscriptions s ON s.customer_id=co.customer_id GROUP BY g.cohort_month,g.n,g.cohort_size ORDER BY g.cohort_month,g.n;
-- Q27 [Advanced] Churn-risk segment using tenure, channel, and ticket volume
WITH t AS (SELECT customer_id,COUNT(*) AS ticket_count FROM support_tickets GROUP BY customer_id), x AS (SELECT c.customer_id,c.acquisition_channel,s.status,s.start_date,s.end_date,COALESCE(t.ticket_count,0) AS ticket_count,CAST(julianday(COALESCE(s.end_date,'2024-12-31'))-julianday(s.start_date) AS INTEGER) AS tenure_days FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id LEFT JOIN t ON t.customer_id=c.customer_id) SELECT customer_id,acquisition_channel,status,tenure_days,ticket_count,CASE WHEN status='cancelled' AND tenure_days<=90 THEN 'Churned early' WHEN status='active' AND tenure_days<=90 AND (acquisition_channel='Paid Search' OR ticket_count>=2) THEN 'High risk' WHEN status='active' AND tenure_days<=180 THEN 'Watch' ELSE 'Lower risk' END AS churn_segment FROM x ORDER BY churn_segment,customer_id;
-- Q28 [Advanced] Best acquisition channel and starting plan for 12-month retention among observable cohorts
WITH eligible AS (SELECT c.acquisition_channel,pl.plan_name,s.customer_id,s.start_date,s.end_date FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id JOIN plans pl ON pl.plan_id=s.plan_id WHERE date(s.start_date,'+12 months')<='2024-12-31') SELECT acquisition_channel,plan_name,COUNT(*) AS eligible_customers,COUNT(CASE WHEN end_date IS NULL OR end_date>=date(start_date,'+12 months') THEN 1 END) AS retained_12m,ROUND(1.0*COUNT(CASE WHEN end_date IS NULL OR end_date>=date(start_date,'+12 months') THEN 1 END)/COUNT(*),4) AS retention_12m FROM eligible GROUP BY acquisition_channel,plan_name ORDER BY retention_12m DESC,eligible_customers DESC;
